 static String unescape(String s)throws IOException{StringBuilder b=new StringBuilder();for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c=='\\'){if(++i>=s.length())throw new IOException();char n=s.charAt(i);if(n=='n'||n=='N')b.append('\n');else if(n=='\\'||n==','||n==';')b.append(n);else throw new IOException();}else b.append(c);}return b.toString();}
