 static long parse(String s,boolean day)throws Exception{if(!s.matches(day?"[0-9]{8}":"[0-9]{8}T[0-9]{6}Z"))throw new IOException();SimpleDateFormat f=new SimpleDateFormat(day?"yyyyMMdd":"yyyyMMdd'T'HHmmss'Z'",Locale.ROOT);f.setTimeZone(TimeZone.getTimeZone("UTC"));f.setLenient(false);return f.parse(s).getTime();}
 static void line(StringBuilder b,String s){int n=0;for(int at=0;at<s.length();){int cp=s.codePointAt(at);String unit=new String(Character.toChars(cp));int bytes;try{bytes=unit.getBytes("UTF-8").length;}catch(Exception e){throw new IllegalStateException(e);}if(n+bytes>72){b.append("\r\n ");n=1;}b.append(unit);n+=bytes;at+=Character.charCount(cp);}b.append("\r\n");}
 static String encode(JSONArray rows)throws Exception{CalendarArchive.validate(rows);StringBuilder b=new StringBuilder("BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Leo//Calendar//RO\r\n");for(int i=0;i<rows.length();i++){JSONObject e=rows.getJSONObject(i);boolean day=e.getInt("allDay")==1;line(b,"BEGIN:VEVENT");line(b,"UID:leo-"+UUID.randomUUID()+"@local");line(b,"DTSTAMP:"+date(System.currentTimeMillis(),false));line(b,"SUMMARY:"+escape(e.getString("title")));line(b,"DTSTART"+(day?";VALUE=DATE":"")+":"+date(e.getLong("start"),day));if(e.isNull("rule"))line(b,"DTEND"+(day?";VALUE=DATE":"")+":"+date(e.getLong("end"),day));else{line(b,"DURATION:"+e.getString("duration"));line(b,"RRULE:"+e.getString("rule"));line(b,"X-LEO-TZ:"+e.getString("zone"));}line(b,"END:VEVENT");}b.append("END:VCALENDAR\r\n");return b.toString();}
 static JSONArray decode(InputStream in)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] block=new byte[4096];int n;while((n=in.read(block))!=-1){if(bytes.size()+n>524288)throw new IOException();bytes.write(block,0,n);}java.nio.charset.CharsetDecoder decoder=java.nio.charset.StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT);String text=decoder.decode(java.nio.ByteBuffer.wrap(bytes.toByteArray())).toString();String[] lines=text.replace("\r\n","\n").replaceAll("\n[ \t]","").split("\n");JSONArray out=new JSONArray();JSONObject e=null;boolean calendar=false,ended=false,version=false;HashSet<String> seen=new HashSet<String>();for(String l:lines){if(l.isEmpty())continue;if(l.equals("BEGIN:VCALENDAR")){if(calendar||ended)throw new IOException();calendar=true;continue;}if(l.equals("END:VCALENDAR")){if(!calendar||e!=null)throw new IOException();calendar=false;ended=true;continue;}if(!calendar)throw new IOException();if(l.equals("BEGIN:VEVENT")){if(e!=null||out.length()>=500)throw new IOException();e=new JSONObject().put("title","Eveniment").put("zone","UTC").put("allDay",0).put("end",JSONObject.NULL).put("rule",JSONObject.NULL).put("duration",JSONObject.NULL).put("alerts",new JSONArray());seen.clear();continue;}if(l.equals("END:VEVENT")){if(e==null||!e.has("start")||!e.isNull("rule")&&!e.isNull("end")||e.isNull("rule")&&!e.isNull("duration"))throw new IOException();if(e.has("endDateOnly")&&((e.getInt("allDay")==1)!=e.getBoolean("endDateOnly")))throw new IOException();e.remove("endDateOnly");out.put(e);e=null;continue;}int at=l.indexOf(':');if(at<=0)throw new IOException();String key=l.substring(0,at),value=l.substring(at+1);if(e==null){if(key.equals("VERSION")){if(version||!value.equals("2.0"))throw new IOException();version=true;}if(!key.equals("VERSION")&&!key.equals("PRODID")&&!key.equals("CALSCALE"))throw new IOException();continue;}if(!seen.add(key.split(";",2)[0]))throw new IOException();if(key.equals("SUMMARY"))e.put("title",unescape(value));else if(key.equals("DTSTART")||key.equals("DTSTART;VALUE=DATE")){boolean day=key.endsWith("DATE");e.put("start",parse(value,day)).put("allDay",day?1:0);}else if(key.equals("DTEND")||key.equals("DTEND;VALUE=DATE")){e.put("end",parse(value,key.endsWith("DATE"))).put("endDateOnly",key.endsWith("DATE"));}else if(key.equals("RRULE"))e.put("rule",value);else if(key.equals("DURATION"))e.put("duration",value);else if(key.equals("X-LEO-TZ"))e.put("zone",value);else if(!key.equals("UID")&&!key.equals("DTSTAMP"))throw new IOException();}if(!ended||calendar||e!=null||!version)throw new IOException();CalendarArchive.validate(out);return out;}
 static String identity(JSONObject e)throws Exception{return new JSONArray().put(e.getString("title")).put(e.getLong("start")).put(e.opt("end")).put(e.opt("rule")).put(e.opt("duration")).put(e.getInt("allDay")).put(e.isNull("rule")?"":e.getString("zone")).toString();}
 static int append(Context c,JSONArray rows)throws Exception{CalendarArchive.validate(rows);JSONArray existing=CalendarArchive.snapshot(c);Set<String> known=new HashSet<String>();for(int i=0;i<existing.length();i++)known.add(identity(existing.getJSONObject(i)));ArrayList<ContentProviderOperation> ops=new ArrayList<ContentProviderOperation>();long id=CalendarArchive.ensure(c);for(int i=0;i<rows.length();i++){JSONObject e=rows.getJSONObject(i);if(!known.add(identity(e)))continue;ContentValues v=new ContentValues();v.put("calendar_id",id);v.put("title",e.getString("title"));v.put("dtstart",e.getLong("start"));v.put("allDay",e.getInt("allDay"));v.put("eventTimezone",e.getString("zone"));v.put("hasAlarm",0);if(e.isNull("rule"))v.put("dtend",e.getLong("end"));else{v.put("rrule",e.getString("rule"));v.put("duration",e.getString("duration"));}ops.add(ContentProviderOperation.newInsert(CalendarContract.Events.CONTENT_URI).withValues(v).build());}if(existing.length()+ops.size()>500)throw new IOException();if(!ops.isEmpty())c.getContentResolver().applyBatch(CalendarContract.AUTHORITY,ops);CalendarReminders.schedule(c);return ops.size();}
